exercise.solution:
use std::collections::HashMap;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
enum Command {
    Add(String, u32),
    Remove(String, u32),
    Report,
}

#[derive(Debug, PartialEq)]
enum StockError {
    UnknownCommand(String),
    MissingArgument,
    BadNumber,
    NotEnough { item: String, have: u32, wanted: u32 },
}

impl fmt::Display for StockError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            StockError::UnknownCommand(word) => write!(f, "unknown command '{word}'"),
            StockError::MissingArgument => write!(f, "missing item or amount"),
            StockError::BadNumber => write!(f, "the amount must be a whole number"),
            StockError::NotEnough { item, have, wanted } => {
                write!(f, "only {have} {item} in stock, wanted {wanted}")
            }
        }
    }
}

// Lets ? turn a ParseIntError into a StockError.
impl From<ParseIntError> for StockError {
    fn from(_: ParseIntError) -> StockError {
        StockError::BadNumber
    }
}

fn parse(line: &str) -> Result<Command, StockError> {
    let mut words = line.split_whitespace();
    let verb = words.next().unwrap_or("");
    let item = words.next();
    let amount = words.next();
    match (verb, item, amount) {
        ("report", _, _) => Ok(Command::Report),
        ("add", Some(item), Some(amount)) => Ok(Command::Add(item.to_string(), amount.parse()?)),
        ("remove", Some(item), Some(amount)) => {
            Ok(Command::Remove(item.to_string(), amount.parse()?))
        }
        ("add" | "remove", _, _) => Err(StockError::MissingArgument),
        _ => Err(StockError::UnknownCommand(verb.to_string())),
    }
}

fn report(stock: &HashMap<String, u32>) -> String {
    let mut names: Vec<_> = stock.keys().collect();
    names.sort();
    let parts: Vec<String> = names
        .into_iter()
        .filter(|name| stock[*name] > 0)
        .map(|name| format!("{name}={}", stock[name]))
        .collect();
    if parts.is_empty() {
        String::from("(empty)")
    } else {
        parts.join(", ")
    }
}

fn apply(stock: &mut HashMap<String, u32>, command: Command) -> Result<String, StockError> {
    match command {
        Command::Add(item, amount) => {
            let message = format!("added {amount} {item}");
            *stock.entry(item).or_insert(0) += amount;
            Ok(message)
        }
        Command::Remove(item, amount) => {
            let have = *stock.get(&item).unwrap_or(&0);
            if have < amount {
                return Err(StockError::NotEnough { item, have, wanted: amount });
            }
            let message = format!("removed {amount} {item}");
            stock.insert(item, have - amount);
            Ok(message)
        }
        Command::Report => Ok(report(stock)),
    }
}

fn run_line(stock: &mut HashMap<String, u32>, line: &str) -> Result<String, StockError> {
    let command = parse(line)?;
    apply(stock, command)
}

fn main() {
    assert_eq!(parse("report"), Ok(Command::Report));
    assert_eq!(parse("add apple 5"), Ok(Command::Add(String::from("apple"), 5)));
    assert_eq!(parse("sell apple 1"), Err(StockError::UnknownCommand(String::from("sell"))));
    println!("parse checks passed");

    let script = [
        "report",
        "add apple 5",
        "add pear 2",
        "add apple 3",
        "remove pear 2",
        "remove apple 10",
        "remove kiwi 1",
        "add plum",
        "add plum lots",
        "sell apple 1",
        "",
        "report",
    ];
    let mut stock = HashMap::new();
    for line in script {
        println!("> {line:?}");
        match run_line(&mut stock, line) {
            Ok(message) => println!("{message}"),
            Err(e) => println!("error: {e}"),
        }
    }
}
